  "repair_strategy": "Update the tabbable node cache in checkFocusIn before attempting focus restoration, and verify the most recently focused node is still connected and focusable; otherwise fall back to the initial focus node (first tabbable node in the updated cache).",
  "edits": [
    {
      "path": "index.js",
      "sha256": "5a4e96cb8f9bb206fe799f923488aab6f2f6d9fc4f1f9fc6023f04aa63ad9a0d",
      "before": "  // In case focus escapes the trap for some strange reason, pull it back in.
  const checkFocusIn = function (e) {
    const target = getActualTarget(e);
    const targetContained = findContainerIndex(target, e) >= 0;

    // In Firefox when you Tab out of an iframe the Document is briefly focused.
    if (targetContained || target instanceof Document) {
      if (targetContained) {
        state.mostRecentlyFocusedNode = target;
      }
    } else {
      // escaped! pull it back in to where it just left
      e.stopImmediatePropagation();
      tryFocus(state.mostRecentlyFocusedNode || getInitialFocusNode());
    }
  };",
      "after": "  // In case focus escapes the trap for some strange reason, pull it back in.
  const checkFocusIn = function (e) {
    const target = getActualTarget(e);
    const targetContained = findContainerIndex(target, e) >= 0;

    // In Firefox when you Tab out of an iframe the Document is briefly focused.
    if (targetContained || target instanceof Document) {
      if (targetContained) {
        state.mostRecentlyFocusedNode = target;
      }
    } else {
      // escaped! pull it back in to where it just left
      e.stopImmediatePropagation();
      // Ensure tabbable nodes are up to date in case the DOM changed (e.g., focused element removed)
      updateTabbableNodes();
      const focusNode = state.mostRecentlyFocusedNode;
      if (!focusNode || !focusNode.isConnected || !isFocusable(focusNode, config.tabbableOptions)) {
        tryFocus(getInitialFocusNode());
      } else {
        tryFocus(focusNode);
      }
    }
  };"
    }
  ],
  "expected_accessibility_effect": "Keyboard focus remains trapped inside the dialog after activating a control that removes itself, ensuring users can continue navigating via Tab/Shift+Tab without escaping.",
  "functional_risks": [
    "Calling updateTabbableNodes on every focus escape adds minimal overhead (rare event).",
    "If isFocusable throws for certain nodes, the guard prevents exceptions but may cause unexpected fallback.",
    "Altered focus restoration logic might affect edge cases where a detached node is legitimately the intended restore target (unlikely)."
  ],
  "verification_requirements": [
    "After clicking 'Show all 4 results', pressing Tab should move focus to the next focusable element inside the dialog (e.g., first list item or close button).",
    "Escape key should still close the dialog and return focus to the opener button.",
    "Opening the dialog should still place initial focus on the close button.",
    "Removing other focusable elements inside the dialog should not break the trap's ability to retain focus."
  ]
}

